  public getSku(sku: string): IMasterSkuSpec | undefined {
    return this.catalog.get(sku);
  }

  public calculateCubeFeet(sku: string): number {
    const item = this.getSku(sku);
    if (!item) return 0.5;
    return +((item.unitLengthInches * item.unitWidthInches * item.unitHeightInches) / 1728).toFixed(3);
  }
